// Custom Cloudflare Worker entry: the OpenNext-generated Next.js worker plus a
// `scheduled` handler for the cron triggers in wrangler.jsonc. Each cron calls
// the protected /api/cron/<job> route on the same worker.
//
// Closed mode: when the central console removes a dealer it sets the Worker
// secret SITE_SUSPENDED=1. Every page and API call then gets a "closed" page
// (only the health check still answers) and scheduled jobs stop. Undoing the
// removal deletes the secret.
// @ts-expect-error -- generated by `opennextjs-cloudflare build`
import { default as handler } from "./.open-next/worker.js";

interface Env {
  CRON_SECRET?: string;
  SITE_SUSPENDED?: string;
  [key: string]: unknown;
}

const JOBS_BY_CRON: Record<string, string[]> = {
  "*/15 * * * *": ["showroom-sweep"],
  "*/30 * * * *": ["orphan-uploads"],
  "0 6 * * *": ["cazoo-health"],
};

const CLOSED_PAGE = `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Closed</title><meta name="robots" content="noindex">
<style>body{font-family:system-ui,Arial,sans-serif;background:#f8fafc;color:#0f172a;display:grid;place-items:center;min-height:100vh;margin:0}
main{max-width:28rem;padding:2rem;text-align:center}h1{font-size:1.4rem}p{color:#475569;line-height:1.5}</style></head>
<body><main><h1>This site is closed</h1><p>This stock book is no longer available. If you think this is a mistake, please contact the business directly.</p></main></body></html>`;

function isSuspended(env: Env): boolean {
  return env.SITE_SUSPENDED === "1";
}

export default {
  fetch(request: Request, env: Env, ctx: { waitUntil(p: Promise<unknown>): void }): Response | Promise<Response> {
    if (isSuspended(env) && new URL(request.url).pathname !== "/api/healthz") {
      const wantsJson = new URL(request.url).pathname.startsWith("/api/");
      return wantsJson
        ? Response.json({ error: "site_closed", message: "This site is closed." }, { status: 503 })
        : new Response(CLOSED_PAGE, { status: 503, headers: { "content-type": "text/html; charset=utf-8", "cache-control": "no-store" } });
    }
    return handler.fetch(request, env, ctx);
  },

  async scheduled(
    event: { cron: string },
    env: Env,
    ctx: { waitUntil(p: Promise<unknown>): void },
  ): Promise<void> {
    if (isSuspended(env)) return; // removed dealer: no imports, sweeps or emails
    const jobs = JOBS_BY_CRON[event.cron] ?? [];
    for (const job of jobs) {
      const req = new Request(`https://cron.internal/api/cron/${job}`, {
        headers: { authorization: `Bearer ${env.CRON_SECRET ?? ""}` },
      });
      ctx.waitUntil(
        handler.fetch(req, env, ctx).then(async (res: Response) => {
          console.log(JSON.stringify({ level: "info", msg: "cron job finished", job, status: res.status, body: await res.text() }));
        }),
      );
    }
  },
};
